/*
Reproduce an image by Fricke and Klein over a century ago.

It's Fig 156 in the book

    "Vorlesungen uber die Theorie der automorphen Funktionen,
     Teubner Leipzig, Germany, 1897."

The coloring and circle parameters are taken from

    https://images-archive.math.cnrs.fr/Un-ensemble-limite.html?lang=fr

Controls:

1. Use mouse to pan
2. Press W/S to zoom in/out
*/

#define PI 3.141592653589793
#define MAX_ITER 1000
#define CURVE_THICKNESS 0.006
#define AA 3

float zoom;

// Pixels near the center of a circle will be inverted to
// very far away and have too large scales. This causes such
// pixels to be incorrectly rendered.
// For such pixels, scale will be roughly the square of |z|,
// where z is the final location in the fundamental domain.
// so add a squared term to fix this.
bool Equal(vec2 z, vec2 a, float scale) {
    float k = 1. + length(z);
    return k * length(z - a) / (scale * zoom) < CURVE_THICKNESS;
}

const vec2 z2 = vec2(0.068, -0.272);
const vec2 z3 = vec2(0.426, -0.672);
const vec2 z4 = vec2(0.816, 0.362);
const vec2 z5 = vec2(-1.154, 0.854);
const float r1 = 0.4;

const float d23 = length(z3 - z2);
const float d34 = length(z3 - z4);
const float d24 = length(z4 - z2);
const float d45 = length(z4 - z5);

const float r2 = (d23 + d24 - d34) / 2.0;
const float r3 = (d23 + d34 - d24) / 2.0;
const float r4 = (d24 + d34 - d23) / 2.0;
const float r5 = d45 - r4;

const float a = r5 + r1;
const float b = r2 + r1;
const float c = length(z2 - z5);

vec2 z1;
vec2 u24, u23, u34, u12, u15, u45;
vec2 zr1;
float rr1;

vec2 circles[5];
float radii[5];

bool region1(vec2 z) { return length(z - zr1) < rr1; }

bool region2(vec2 z) {
    return cross2d(z, u12, u24) > 0. && cross2d(z, u24, u45) > 0. &&
           cross2d(z, u45, u15) > 0. && cross2d(z, u15, u12) > 0.;
}

vec3 getColor(vec2 z) {
    vec2 w = z;
    int count = 0;
    vec3 color = RED;
    float scale = 1.0;

    for (int i = 0; i < MAX_ITER; i++) {
        for (int j = 0; j < 6; j++) {
            vec2 p = vec2[6](u12, u15, u23, u24, u34, u45)[j];
            if (Equal(z, p, scale)) {
                return BLACK;
            }
        }

        bool found = true;
        for (int j = 0; j < 5; j++) {
            if (length(z - circles[j]) < radii[j]) {
                z = invert(z, circles[j], radii[j], scale);
                count++;
                found = false;
            }
        }

        if (found) {
            if (region1(z)) {
                color = (count % 2 == 0) ? BROWN : YELLOW;
            } else if (region2(z)) {
                color = (count % 2 == 0) ? GREEN : LTGREEN;
            } else {
                color = (count % 2 == 0) ? VIOLET : LTVIOLET;
            }
            break;
        }
    }

    float d = 1e5;
    for (int j = 0; j < 5; j++) {
        float d1 = abs(length(w - circles[j]) - radii[j]) - 0.002;
        d = min(d, d1);
    }
    d = smoothstep(0., 0.003, d);
    color = mix(vec3(1.0), color, d);
    return color;
}

void init() {
    z1 = findThirdVertex(z2, z5, a, b, c);
    u24 = getTouchPoint(z2, r2, z4);
    u23 = getTouchPoint(z2, r2, z3);
    u34 = getTouchPoint(z3, r3, z4);
    u12 = getTouchPoint(z1, r1, z2);
    u15 = getTouchPoint(z1, r1, z5);
    u45 = getTouchPoint(z4, r4, z5);
    zr1 = circumcenter(u23, u24, u34);
    rr1 = length(u24 - zr1);

    circles[0] = z1;
    circles[1] = z2;
    circles[2] = z3;
    circles[3] = z4;
    circles[4] = z5;
    radii[0] = r1;
    radii[1] = r2;
    radii[2] = r3;
    radii[3] = r4;
    radii[4] = r5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    init();
    vec4 pan_vals = textureLod(iChannel0, vec2(0.0, 0.0), 0.0);
    zoom = textureLod(iChannel0, vec2(10.5, 10.5) / iResolution.xy, 0.0).x;
    vec3 col = vec3(0);
    for (int ii = 0; ii < AA; ii++) {
        for (int jj = 0; jj < AA; jj++) {
            vec2 o = vec2(float(ii), float(jj)) / float(AA);
            vec2 uv = (2. * (fragCoord + o) - iResolution.xy -
                       pan_vals.xy * pow(zoom, -1.0)) /
                      iResolution.y;
            uv *= zoom * 0.8;
            col += getColor(uv);
        }
    }
    col /= (float(AA) * float(AA));
    fragColor = vec4(col, 1.0);
}

#define L2(x) dot(x, x)

const vec3 BLACK = vec3(0.0);
const vec3 RED = vec3(1.0, 0.0, 0.0);
const vec3 VIOLET = vec3(0.39, 0.16, 0.71);
const vec3 GREEN = vec3(0.0, 0.5, 0.0);
const vec3 YELLOW = vec3(0.78, 0.78, 0.0);
const vec3 BROWN = vec3(0.75, 0.5, 0.0);
const vec3 LTGREEN = vec3(0.36, 0.88, 0.25);
const vec3 LTVIOLET = vec3(0.78, 0.39, 1.0);

vec2 findThirdVertex(vec2 z, vec2 w, float a, float b, float c) {
    vec2 d = z - w;
    d /= length(d);
    float k = (a * a - b * b + c * c) / (2.0 * c);
    float h = sqrt(a * a - k * k);
    return w + vec2(d.x * k + d.y * h, d.y * k - d.x * h);
}

vec2 circumcenter(vec2 A, vec2 B, vec2 C) {
    float dx = B.x - A.x;
    float dy = B.y - A.y;
    float ex = C.x - A.x;
    float ey = C.y - A.y;
    float bl = dx * dx + dy * dy;
    float cl = ex * ex + ey * ey;
    float d = 0.5 / (dx * ey - dy * ex);
    float x = A.x + (ey * bl - dy * cl) * d;
    float y = A.y + (dx * cl - ex * bl) * d;
    return vec2(x, y);
}

vec2 getTouchPoint(vec2 z1, float r1, vec2 z2) {
    vec2 d = z2 - z1;
    d /= length(d);
    return d * r1 + z1;
}

float cross2d(vec2 A, vec2 B, vec2 C) {
    vec2 AB = B - A;
    vec2 AC = C - A;
    return AB.x * AC.y - AB.y * AC.x;
}

vec2 invert(vec2 z, vec2 cen, float r, inout float scale) {
    float k = (r * r) / dot(z - cen, z - cen);
    scale *= k;
    return cen + k * (z - cen);
}

// https://www.shadertoy.com/view/ldyGzW
const int Key_A = 65;
const int Key_B = 66;
const int Key_C = 67;
const int Key_D = 68;
const int Key_E = 69;
const int Key_F = 70;
const int Key_G = 71;
const int Key_H = 72;
const int Key_I = 73;
const int Key_J = 74;
const int Key_K = 75;
const int Key_L = 76;
const int Key_M = 77;
const int Key_N = 78;
const int Key_O = 79;
const int Key_P = 80;
const int Key_Q = 81;
const int Key_R = 82;
const int Key_S = 83;
const int Key_T = 84;
const int Key_U = 85;
const int Key_V = 86;
const int Key_W = 87;
const int Key_X = 88;
const int Key_Y = 89;
const int Key_Z = 90;
const int Key_0 = 48;
const int Key_1 = 49;
const int Key_2 = 50;
const int Key_3 = 51;
const int Key_4 = 52;
const int Key_5 = 53;
const int Key_6 = 54;
const int Key_7 = 55;
const int Key_8 = 56;
const int Key_9 = 57;
const int Key_Space = 32;

float ReadKeyInternal(int key, bool toggle) {
    return textureLod(iChannel1,
                      vec2((float(key) + .5) / 256.0, toggle ? .75 : .25), 0.0)
        .x;
}

float ReadKey(int key) { return ReadKeyInternal(key, false); }

float ReadKeyToggle(int key) { return ReadKeyInternal(key, true); }

// Storage Code For Pan and Zoom

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    // Only run once each frame

    if (ivec2(fragCoord.xy) == ivec2(0, 0)) {
        // Mouse Pan Stored In Here

        vec4 prev_info = textureLod(iChannel0, vec2(0.0, 0.0), 0.0);
        float Zoom =
            textureLod(iChannel0, vec2(10.5, 10.5) / iResolution.xy, 0.0).x;
        float prev_pan_x = prev_info.x;
        float prev_pan_y = prev_info.y;

        float legacy_pan_x = prev_info.z;
        float legacy_pan_y = prev_info.w;

        float pan_x = (iMouse.x - abs(iMouse.z)) * Zoom + legacy_pan_x;
        float pan_y = (iMouse.y - abs(iMouse.w)) * Zoom + legacy_pan_y;

        if (iMouse.z < 0.0) {
            // Mouse has been lifted up
            legacy_pan_x = prev_pan_x;
            legacy_pan_y = prev_pan_y;
            pan_x = legacy_pan_x;
            pan_y = legacy_pan_y;
        }

        fragColor = vec4(pan_x, pan_y, legacy_pan_x, legacy_pan_y);
    }

    // Zoom settings
    if (ivec2(fragCoord.xy) == ivec2(10, 10)) {

        float x =
            textureLod(iChannel0, vec2(10.5, 10.5) / iResolution.xy, 0.0).y;
        // Number of times zoom in - zoom out has happend

        x += ReadKey(Key_W) - ReadKey(Key_S);

        float Zoom = pow(2.71, -x * 0.05); // Times all limits by this value

        fragColor = vec4(Zoom, x, 0.0, 0.0);
    }
}
